// The library rides along because the template editor's homework items pick from it,
// and two reads for one page would be two ways to fail.
(async () => {
  try {
    const q = (c) => Noodl.Records.query(c, {}, { limit: 1000, plain: true });
    const library = await q('LibraryItem');
    const titleOf = (id) => (library.find((l) => l.objectId === id) || {}).title || '';
    Outputs.templates = (await q('PlanTemplate'))
      .map((t) => ({
        id: t.objectId,
        title: t.title || '',
        description: t.description || '',
        archived: t.archived === true,
        items: (Array.isArray(t.items) ? t.items : []).map((i) => ({
          kind: i.kind,
          title: i.title || '',
          durationMin: Number.isInteger(i.durationMin) ? i.durationMin : null,
          libraryItem: i.libraryItem || '',
          libraryTitle: i.libraryItem ? titleOf(i.libraryItem) : '',
          dayOffset: Number.isInteger(i.dayOffset) ? i.dayOffset : 0
        }))
      }))
      .sort((a, b) => a.title.localeCompare(b.title));
    Outputs.library = library
      .map((l) => ({ id: l.objectId, title: l.title || '', archived: l.archived === true }))
      .sort((a, b) => a.title.localeCompare(b.title));
    Outputs.done();
  } catch (e) {
    console.error('[dbu:planTemplates]', String((e && e.message) || e));
    Outputs.failed();
  }
})();
